    const hasEmpty = txt.includes("Oops, we have nothing to show!");
    const tds = $body.find("table tbody tr td").length;
    cy.log("TERM[" + term + "] showing='" + showing + "' empty=" + hasEmpty + " rows=" + tds / 6);
    if (tds >= 6) {
      cy.log("TERM[" + term + "] firstRow=" + $body.find("table tbody tr").first().text().trim().slice(0, 180));
    }
  });
